"""Simulated class signatures from a small reference set generated by the repo's own
scripts/generate_sims.py (--out annotation_review/sim_ref --n-values 10 30 70 --seeds 4),
using the repo's window feature code. Fits a Gaussian classifier on 5-frame windows."""
import json, joblib
import numpy as np, pandas as pd
from common import REVIEW, ROOT
from src.features.dataset import build_sim_xy
from src.features.order_params import AGG_FEATURE_NAMES
from sklearn.discriminant_analysis import QuadraticDiscriminantAnalysis
from sklearn.model_selection import cross_val_score

X, y, names = build_sim_xy(manifest_path=REVIEW/"sim_ref"/"manifest.json", include_transitions=False)
df = pd.DataFrame(X, columns=names); df["label"] = y
sig = df.groupby("label").agg(["mean", "std"])
sig.to_csv(REVIEW/"sim_signatures.csv")
print(df.label.value_counts().to_dict())
print(df.groupby("label").mean().round(3).to_string())
clf = QuadraticDiscriminantAnalysis(reg_param=0.05)
print("QDA 5-fold CV acc on sim windows:", cross_val_score(clf, X, y, cv=5).mean().round(3))
clf.fit(X, y)
joblib.dump({"clf": clf, "names": names}, REVIEW/"sim_qda.joblib")
